def stable_top_k(items, k):
    if k == 0:
        return []
    ranked = sorted(items, key=lambda item: (-item["score"], item["id"]))
    return [item["id"] for item in ranked[:k]]

def merge_intervals(intervals):
    if not intervals:
        return []
    values = sorted(intervals)
    out = [values[0][:]]
    for start, end in values[1:]:
        if start <= out[-1][1] + 1:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def largest_remainder(total, weights):
    if total < 0 or any(w < 0 for w in weights):
        raise ValueError("negative")
    s = sum(weights)
    if not s:
        raise ValueError("zero")
    raw = [total * w / s for w in weights]
    result = [round(x) for x in raw]
    while sum(result) < total:
        result[result.index(min(result))] += 1
    while sum(result) > total:
        result[result.index(max(result))] -= 1
    return result

def dedupe_events(events):
    chosen = {}
    for event in events:
        if event["id"] not in chosen or event["seq"] > chosen[event["id"]]["seq"]:
            chosen[event["id"]] = event
    return [dict(event) for event in chosen.values()]

def apply_edits(text, edits):
    value = text
    for edit in edits:
        start, end = edit["start"], edit["end"]
        value = value[:start] + edit["replacement"] + value[end:]
    return value

def quorum_decision(votes, quorum):
    if quorum <= 0:
        raise ValueError("quorum")
    if len(votes) < quorum:
        return "no-quorum"
    yes = votes.count("yes")
    no = votes.count("no")
    return "yes" if yes > no else "no"

def chunk_windows(items, size, overlap):
    if size <= 0 or overlap < 0:
        raise ValueError("invalid")
    step = size - overlap
    return [items[i:i+size] for i in range(0, len(items)-size+1, step)]

def select_latest(records):
    out = {}
    for record in records:
        key = record["key"]
        if key not in out or record["revision"] > out[key]["revision"]:
            out[key] = record
    return [dict(out[key]) for key in sorted(out)]
